using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class ProgramReadinessReportTests{[Fact]public void Source_only_program_remains_candidate_not_stable(){var m=ReleaseValidationMatrixRules.Create(true,null,null);var r=ReleaseCandidateSummaryRules.Create("1","1","c","t",m,m);var g=TestFixtures.Gates();var w=ProductResearchWorkspaceDashboardRules.Create(ResearchWorkspaceIndexRules.Create(new[]{ResearchWorkspaceIndexRules.From(g)}));var p=ProgramReadinessReportRules.Create(r,w);Assert.True(p.EngineeringCandidate);Assert.False(p.StableEligible);Assert.True(p.SimulationOnly);Assert.False(p.LiveAuthorityEnabled);}}
